window.__votdWeek && window.__votdWeek({"week":"2028-04-24","reading":"Mosiah 4–6","days":[{"d":"2028-04-24","ref":"Mosiah 4:9","b":"Mosiah","c":4,"v":9,"he":"הַאֲמִינוּ בֵּאלֹהִים הַאֲמִינוּ כִּי־הוּא וְכִי בָרָא כׇל־דָּבָר בַּשָּׁמַיִם וּבָאָרֶץ הַאֲמִינוּ כִּי־לוֹ כׇל־חׇכְמָה וְכׇל־גְּבוּרָה בַּשָּׁמַיִם וּבָאָרֶץ הַאֲמִינוּ כִּי־לֹא יָבִין הָאָדָם אֶת־כׇּל־אֲשֶׁר יָבִין יְהוָה׃","en":"Believe in God; believe that he is, and that he created all things, both in heaven and in earth; believe that he has all wisdom, and all power, both in heaven and in earth; believe that man doth not comprehend all the things which the Lord can comprehend."},{"d":"2028-04-25","ref":"Mosiah 4:10","b":"Mosiah","c":4,"v":10,"he":"וְעוֹד הַאֲמִינוּ כִּי עֲלֵיכֶם לָשׁוּב מֵחַטֹּאתֵיכֶם וְלַעֲזֹב אוֹתָם וּלְהִשְׁפִּיל נַפְשְׁכֶם לִפְנֵי אֱלֹהִים וּלְבַקֵּשׁ בְּלֵב תָּמִים כִּי יִסְלַח לָכֶם וְעַתָּה אִם־תַּאֲמִינוּ בְּכׇל־אֵלֶּה רְאוּ לַעֲשׂוֹתָם׃","en":"And again, believe that ye must repent of your sins and forsake them, and humble yourselves before God; and ask in sincerity of heart that he would forgive you; and now, if you believe all these things see that ye do them."},{"d":"2028-04-26","ref":"Mosiah 4:23","b":"Mosiah","c":4,"v":23,"he":"אֹמֵר אֲנִי לָכֶם אוֹי לָאִישׁ הַהוּא כִּי רְכוּשׁוֹ יֹאבַד עִמּוֹ וְעַתָּה אֹמֵר אֲנִי אֶת־הַדְּבָרִים הָאֵלֶּה לָעֲשִׁירִים בְּעִנְיְנֵי הָעוֹלָם הַזֶּה׃","en":"I say unto you, wo be unto that man, for his substance shall perish with him; and now, I say these things unto those who are rich as pertaining to the things of this world."},{"d":"2028-04-27","ref":"Mosiah 5:3","b":"Mosiah","c":5,"v":3,"he":"וְגַם־אֲנַחְנוּ בְּחֶסֶד אֱלֹהִים אֲשֶׁר אֵין־לוֹ קֵץ וּבְהִגָּלוֹת רוּחוֹ חָזִינוּ חֲזוֹנוֹת גְּדוֹלִים עַל־הַבָּאוֹת וְלוּ הָיָה נָכוֹן הָיִינוּ נִבָּאִים עַל־כׇּל־דָּבָר׃","en":"And we, ourselves, also, through the infinite goodness of God, and the manifestations of his Spirit, have great views of that which is to come; and were it expedient, we could prophesy of all things."},{"d":"2028-04-28","ref":"Mosiah 5:4","b":"Mosiah","c":5,"v":4,"he":"וַתְּבִיאֵנוּ הָאֱמוּנָה אֲשֶׁר הָיְתָה לָנוּ בַּדְּבָרִים אֲשֶׁר־דִּבֶּר מַלְכֵּנוּ אֶל־הַדַּעַת הַגְּדוֹלָה הַזֹּאת אֲשֶׁר בָּהּ נָגִילָה וְנִשְׂמְחָה שִׂמְחָה גְדוֹלָה מְאֹד׃","en":"And it is the faith which we have had on the things which our king has spoken unto us that has brought us to this great knowledge, whereby we do rejoice with such exceedingly great joy."},{"d":"2028-04-29","ref":"Mosiah 5:13","b":"Mosiah","c":5,"v":13,"he":"כִּי אֵיךְ יֵדַע אִישׁ אֶת־הָאָדוֹן אֲשֶׁר לֹא עֲבָדוֹ וְהוּא זָר לוֹ וְרָחוֹק מִמַּחְשְׁבוֹת לִבּוֹ וּמִמְּזִמּוֹתָיו׃","en":"For how knoweth a man the master whom he has not served, and who is a stranger unto him, and is far from the thoughts and intents of his heart?"},{"d":"2028-04-30","ref":"Mosiah 6:4","b":"Mosiah","c":6,"v":4,"he":"וַיָּחֶל מוֹשִׁיָּה לִמְלֹךְ תַּחַת אָבִיו וַיָּחֶל לִמְלֹךְ בִּשְׁנַת הַשְּׁלֹשִׁים לְחַיָּיו וַיְהִי הַכֹּל כְּאַרְבַּע מֵאוֹת וְשִׁבְעִים וָשֵׁשׁ שָׁנִים מֵעֵת אֲשֶׁר יָצָא לֶחִי מִירוּשָׁלָ͏ִם׃","en":"And Mosiah began to reign in his father’s stead. And he began to reign in the thirtieth year of his age, making in the whole, about four hundred and seventy-six years from the time that Lehi left Jerusalem."}]});
